head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd;
scwin.vScrenID = "ULDSTF33020.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_HideDebugCtrls = function() {

};
scwin.fn_SetCode = function() {

};
scwin.fn_Init = function() {
    $c.stf.setObjectValue(rdo_MARKET_TP_CD, js_market);
    if (js_market == "9") {
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        // 콘트롤 잠그기.
        $c.stf.showObj(panel_mkt_gubun, false);
    }
};
scwin.fn_Search = function() {
    if (tab_Main.getSelectedTabIndex() == 1) {
        var url = "/LnkDisclsApplCorp.do?method=selectLnkDisclsApplCorp" + "&SEARCH_TYP=LINK_CORP" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD) + "&LIST_STAT_CD=" + $c.stf.getObjectValue(chb_LIST_STAT_CD) + "&LNK_DISCLS_SUBMIT_CORP_YN=" + $c.stf.getObjectValue(chb_LNK_DISCLS_SUBMIT_CORP_YN);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Tab1.DataID = encodeURI(url);
        dts_Tab1.Reset();
        $c.cm.ShowWin(grd_Tab1);
    } else if (tab_Main.getSelectedTabIndex() == 2) {
        var url = "/LnkDisclsApplCorp.do?method=selectLnkDisclsApplCorp" + "&SEARCH_TYP=NEW_LIST_LINK_CORP" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Tab2.DataID = encodeURI(url);
        dts_Tab2.Reset();
        $c.cm.ShowWin(grd_Tab2);
    } else if (tab_Main.getSelectedTabIndex() == 3) {
        var url = "/LnkDisclsApplCorp.do?method=selectLnkDisclsApplCorp" + "&SEARCH_TYP=DELIST_LINK_CORP" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Tab3.DataID = encodeURI(url);
        dts_Tab3.Reset();
        $c.cm.ShowWin(grd_Tab3);
    }
};
scwin.fn_setId = function(obj) {
    g_hdcom_isur_cd = dts_Tab1.getCellData(eval(obj), "HDCOM_ISUR_CD");
    g_hdcom_com_abbrv = dts_Tab1.getCellData(eval(obj), "HDCOM_COM_ABBRV");
    g_hdcom_lm_mkt_tp_cd = dts_Tab1.getCellData(eval(obj), "HDCOM_LD_MKT_TP_NM");
};
scwin.tab_Main_OnSelChanged = function(nIndex) {
    if (tab_Main.getSelectedTabIndex() == 1) {
        $c.stf.showObj(panel_Chb_Search, true);
    } else {
        $c.stf.showObj(panel_Chb_Search, false);
    }
};
scwin.grd_Tab1_OnDblClick = async function(row, colid) {
    scwin.fn_setId(row);
    if (colid == 'LNK_DISCLS_SUBMIT_DDTM') {
        await $c.frame.CreateFrame("ULDSTF33021" + row, "/issueinfo/ULDSTF33021.gfm", "연계공시 신청내역", 200, 70, 950, 560 + 30, "window", 0, 0, true);
    } else if (colid == 'HDCOM_COM_ABBRV') {
        scwin.gIsurCd = dts_Tab1.getCellData(row, "HDCOM_ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == 'SUBCOM_COM_ABBRV') {
        scwin.gIsurCd = dts_Tab1.getCellData(row, "SUBCOM_ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.grd_Tab2_OnDblClick = function(row, colid) {
    scwin.fn_setId(row);
    if (colid == 'HDCOM_COM_ABBRV') {
        scwin.gIsurCd = dts_Tab2.getCellData(row, "HDCOM_ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == 'SUBCOM_COM_ABBRV') {
        scwin.gIsurCd = dts_Tab2.getCellData(row, "SUBCOM_ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.grd_Tab3_OnDblClick = function(row, colid) {
    scwin.fn_setId(row);
    if (colid == 'HDCOM_COM_ABBRV') {
        scwin.gIsurCd = dts_Tab3.getCellData(row, "HDCOM_ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == 'SUBCOM_COM_ABBRV') {
        scwin.gIsurCd = dts_Tab3.getCellData(row, "SUBCOM_ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    if (tab_Main.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_Tab1, "연계공시법인 현황", "", "8");
    } else if (tab_Main.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_Tab2, "신규상장예정 자회사 현황", "", "8");
    } else if (tab_Main.getSelectedTabIndex() == 3) {
        $c.data.downloadGridViewExcel(grd_Tab3, "상장폐지예정 자회사 현황", "", "8");
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_ISUR_CD_onclick = function() {
    //IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    $c.cm.ListIsurcdSearch(txb_ISUR_CD, txb_COM_NM, '', '');
};
scwin.dts_Tab1_OnLoadError = function() {
    $c.stf.alert_error(dts_Tab1);
};
scwin.dts_Tab2_OnLoadError = function() {
    $c.stf.alert_error(dts_Tab2);
};
scwin.dts_Tab3_OnLoadError = function() {
    $c.stf.alert_error(dts_Tab3);
};
scwin.dts_Tab1_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Tab1);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.dts_Tab2_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Tab2);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.dts_Tab3_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Tab3);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.gform_onload = function() {
    tab_Main.setSelectedTabIndex(1);
    // debug 용 콘트롤들 모두 숨기기.
    scwin.fn_HideDebugCtrls();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    //Grd_com_isur.style.zIndex = 30;

    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.fn_Init();
    scwin.fn_Search();
};
